"""Semantic paper embeddings generated by a CPU sentence-transformers model."""
import math
import os
import threading

from .schema import AcademicPaper

DIM = 384
DEFAULT_MODEL = "sentence-transformers/all-MiniLM-L6-v2"
_MODEL = None
_MODEL_LOCK = threading.Lock()


def _load_model():
    global _MODEL
    if _MODEL is not None:
        return _MODEL
    with _MODEL_LOCK:
        if _MODEL is not None:
            return _MODEL
        from sentence_transformers import SentenceTransformer

        _MODEL = SentenceTransformer(
            os.getenv("EMBEDDING_MODEL", DEFAULT_MODEL),
            device="cpu",
        )
        return _MODEL


def paper_text(paper: AcademicPaper, source: dict | None = None) -> str:
    source = source or {}
    metrics = " ".join(
        f"{metric.name} {metric.value} {metric.unit or ''}"
        for metric in paper.hardware_metrics
    )
    return " ".join(
        part
        for part in (
            paper.title,
            " ".join(paper.authors),
            str(source.get("abstract", "")),
            str(source.get("body", "")),
            metrics,
            " ".join(paper.latex_formulas),
            " ".join(paper.taxonomy_tags),
        )
        if part
    )


def embed_paper(paper: AcademicPaper, source: dict | None = None) -> list[float]:
    vector = _load_model().encode(
        paper_text(paper, source),
        normalize_embeddings=True,
        convert_to_numpy=True,
        show_progress_bar=False,
    ).tolist()
    if len(vector) != DIM:
        raise ValueError(
            f"Embedding model must return {DIM} dimensions; got {len(vector)}"
        )
    if not all(math.isfinite(float(value)) for value in vector):
        raise ValueError("Embedding model returned a non-finite value")
    return [float(value) for value in vector]
